        address owner = c.smartfix_owner();
        bool reverted;

        // The test contract is the deployer, so it is the owner.
        require(owner == address(this), "test contract must be the owner");

        // Deciding call: should succeed because caller == owner.
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
